import { styled } from '@hexa-ui/theme';

export const StyledPortfolioPieChartRoot = styled('div', {
  display: 'flex',
  flexDirection: 'column',
  alignItems: 'stretch',
  width: '100%',
  minWidth: 0,
  boxSizing: 'border-box',
  border: '1px solid #14141429',
  borderRadius: '16px',
  overflow: 'visible',
});

export const StyledPortfolioPieChartTitle = styled('div', {
  padding: '16px 24px 16px 24px',
  borderBottom: '1px solid #14141429',
  boxSizing: 'border-box',
  '& h3': {
    padding: 0,
    margin: 0,
    fontSize: '20px',
    fontWeight: 600,
    lineHeight: '120%',
    color: '#141414',
    width: '100%',
    textAlign: 'left',
    fontFamily: "'Work Sans', sans-serif",
  },
});

export const StyledPortfolioPieChartInner = styled('div', {
  display: 'flex',
  flexDirection: 'column',
  alignItems: 'center',
  justifyContent: 'center',
  width: '100%',
  gap: '12px',
  padding: '16px 0 8px 0',
  boxSizing: 'border-box',
});

export const StyledPortfolioPieLegend = styled('div', {
  display: 'flex',
  flexWrap: 'wrap',
  justifyContent: 'center',
  alignContent: 'center',
  alignItems: 'center',
  gap: '10px 14px',
  width: '100%',
  maxWidth: '100%',
  marginBottom: '12px',
  boxSizing: 'border-box',
  textAlign: 'center',
});

export const StyledPortfolioPieLegendItem = styled('div', {
  display: 'inline-flex',
  alignItems: 'center',
  gap: '4px',
  fontSize: '12px',
  lineHeight: '140%',
  fontFamily: "'Work Sans', sans-serif",
  fontWeight: 400,
  color: '#141414',
});

export const StyledPortfolioPieLegendSwatch = styled('span', {
  display: 'inline-block',
  width: '16px',
  height: '8px',
  borderRadius: '2px',
  flexShrink: 0,
});

export const StyledPortfolioPieChartPlot = styled('div', {
  display: 'flex',
  justifyContent: 'center',
  alignItems: 'center',
  width: '100%',
  flexShrink: 0,
  boxSizing: 'border-box',
  overflow: 'visible',
  alignSelf: 'center',
});
